#pragma once
namespace openp1::network {
constexpr char access_page[]=R"HTML(<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenP1 — Full access required</title><style>:root{font:16px system-ui;color:#193c35;background:#f1f5f3}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px}main{max-width:520px;background:white;border:1px solid #dae5df;border-radius:20px;padding:32px}small{color:#627a70}h1{font-size:30px;letter-spacing:-.04em}p{line-height:1.7}#unlockStatus{padding:12px 16px;background:#edf4f0;border-radius:10px;font-size:14px}</style><main><small>OPENP1 · WEB ACCESS</small><h1>Press S2 to unlock</h1><p>Press and release the S2 button on the module to switch to <strong>Full access</strong> for five minutes.</p><p>This page will open the main page automatically when Full access is available.</p><p id="unlockStatus" role="status" aria-live="polite">Waiting for the button press…</p><small>The S2 button must be enabled in the firmware and correctly connected.</small></main><script>
async function waitForFull(){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch('/access-check',{cache:'no-store',signal:controller.signal});if(r.status===204){location.replace('/');return}document.getElementById('unlockStatus').textContent=r.status===403?'Waiting for the button press…':'Waiting for the module…'}catch{document.getElementById('unlockStatus').textContent='Module unreachable. Reconnecting…'}finally{clearTimeout(timer)}setTimeout(waitForFull,2000)}waitForFull();
</script></html>)HTML";
}
